<?php $pageTitle='Detalle del pedido'; require __DIR__.'/_header.php';$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT * FROM orders WHERE id=?');$q->execute([$id]);$o=$q->fetch();if(!$o){echo '<div class="admin-card">Pedido no encontrado.</div>';require __DIR__.'/_footer.php';exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$new=$_POST['status']??'';$allowed=['received','awaiting_receipt','receipt_received','paid','preparing','ready','on_the_way','delivered','cancelled'];if(in_array($new,$allowed,true)){$u=db()->prepare('UPDATE orders SET status=?,updated_at=NOW() WHERE id=?');$u->execute([$new,$id]);$h=db()->prepare('INSERT INTO order_status_history(order_id,status,note,admin_id,created_at) VALUES(?,?,?,?,NOW())');$h->execute([$id,$new,'Actualizado desde administración',$_SESSION['admin_id']]);$o['status']=$new;}}$q=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$q->execute([$id]);$items=$q->fetchAll();$message="Hola {$o['customer_name']} 👋\nActualización de tu pedido {$o['public_id']}: {$o['status']}.";?><div class="order-layout"><section class="admin-card"><div class="admin-card-head"><div><small>Pedido</small><h2><?=h($o['public_id'])?></h2></div><span class="status-pill"><?=h($o['status'])?></span></div><div class="order-meta"><div><span>Cliente</span><b><?=h($o['customer_name'])?></b></div><div><span>WhatsApp</span><b><?=h($o['whatsapp'])?></b></div><div><span>Dirección</span><b><?=h($o['address'])?></b></div><div><span>Entrega</span><b><?=h($o['delivery_label'])?></b></div></div><h3>Productos</h3><?php foreach($items as $i):?><div class="line"><span><?=h($i['product_name'])?> × <?=h((string)$i['quantity'])?></span><b><?=money((float)$i['line_total'])?></b></div><?php endforeach;?><div class="line"><span>Delivery</span><b><?=money((float)$o['delivery_cost'])?></b></div><div class="line grand"><span>Total</span><b><?=money((float)$o['total'])?></b></div><?php if($o['lat']&&$o['lng']):?><p><a target="_blank" href="https://www.google.com/maps?q=<?=h($o['lat'])?>,<?=h($o['lng'])?>">📍 Abrir ubicación</a></p><?php endif;?><?php if($o['receipt_path']):?><p><a href="file.php?id=<?=$id?>&type=receipt" target="_blank">🧾 Abrir comprobante</a></p><?php endif;?><?php if($o['facade_path']):?><p><a href="file.php?id=<?=$id?>&type=facade" target="_blank">🏠 Ver fachada</a></p><?php endif;?></section><aside class="admin-card"><h3>Cambiar estado</h3><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><select name="status"><?php foreach(['received','awaiting_receipt','receipt_received','paid','preparing','ready','on_the_way','delivered','cancelled'] as $s):?><option <?=$o['status']===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select><button class="btn primary wide">Guardar estado</button></form><a class="btn ghost wide" target="_blank" href="<?=h(whatsapp_url($o['whatsapp'],$message))?>">Notificar por WhatsApp</a><a class="btn ghost wide" target="_blank" href="../tracking.php?token=<?=h($o['public_token'])?>">Ver seguimiento público</a></aside></div><?php require __DIR__.'/_footer.php';?>